// ==============================================================================
// Replay landing page for the CITS3011 Diplomacy agent.
//
// Replaces the server connection page: lists games pre-generated by
// generate_games.py (public/games/index.json) and opens them in the existing
// game viewer, without needing a server. Licensed under the GNU AGPL v3 like
// the rest of this web interface.
// ==============================================================================
import React from 'react';
import {Helmet} from "react-helmet";
import {Navigation} from "../components/navigation";
import {PageContext} from "../components/page_context";
import {ContentGame} from "./content_game";
import {gameFromSavedData} from "../utils/saved_game";
import "./content_replays.css";

const REPO_URL = 'https://github.com/jono1762/diplomacy-agent';
const GAMES_DIR = 'games';

const OUTCOME_CLASSES = {WIN: 'badge-success', SURVIVE: 'badge-secondary', DEFEAT: 'badge-danger'};

function setGameParam(gameId) {
    const url = new URL(window.location.href);
    if (gameId)
        url.searchParams.set('game', gameId);
    else
        url.searchParams.delete('game');
    window.history.replaceState(null, '', url.toString());
}

export class ContentReplays extends React.Component {
    constructor(props) {
        super(props);
        this.state = {games: null};
        this.openGame = this.openGame.bind(this);
    }

    openGame(entry) {
        const page = this.context;
        page.info(`Loading ${entry.id} ...`);
        return fetch(`${GAMES_DIR}/${entry.file}`)
            .then(response => {
                if (!response.ok)
                    throw new Error(`HTTP ${response.status}`);
                return response.json();
            })
            .then(savedData => {
                const game = gameFromSavedData(savedData);
                setGameParam(entry.id);
                return page.load(
                    `game: ${game.game_id}`,
                    <ContentGame data={game} initialTab={'phase_history'} initialPower={entry.power}/>,
                    {success: `Agent playing ${entry.power} ${entry.scenario_title}`}
                );
            })
            .catch(error => page.error(`Unable to load game ${entry.id}: ${error}`));
    }

    renderScenario(scenario, games) {
        return (
            <div key={scenario} className={'mb-4'}>
                <h5>Agent {games[0].scenario_title}</h5>
                <div className={'table-responsive'}>
                    <table className={'table table-striped table-sm replays'}>
                        <thead>
                        <tr>
                            <th>Agent plays</th>
                            <th className={'d-none d-sm-table-cell'}>Opponents</th>
                            <th>Result</th>
                            <th>Agent SCs</th>
                            <th className={'d-none d-sm-table-cell'}>Ended</th>
                            <th/>
                        </tr>
                        </thead>
                        <tbody>
                        {games.map(entry => (
                            <tr key={entry.id}>
                                <td><strong>{entry.power}</strong></td>
                                <td className={'opponents d-none d-sm-table-cell'}>
                                    {Object.entries(entry.agents)
                                        .filter(([power]) => power !== entry.power)
                                        .map(([power, agent]) => `${power.substring(0, 3)}: ${agent}`)
                                        .join(', ')}
                                </td>
                                <td>
                                    <span className={`badge ${OUTCOME_CLASSES[entry.outcome] || 'badge-secondary'}`}>
                                        {entry.outcome}
                                    </span>
                                </td>
                                <td>{entry.centres[entry.power]}</td>
                                <td className={'d-none d-sm-table-cell'}>{entry.end_year}</td>
                                <td>
                                    <button type={'button'} className={'btn btn-primary btn-sm'}
                                            onClick={() => this.openGame(entry)}>Watch</button>
                                </td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    }

    render() {
        const title = 'Diplomacy Agent Replays';
        const page = this.context;
        const navigation = [
            ['Load a game from disk', page.loadGameFromDisk],
            ['Source code on GitHub', () => window.open(REPO_URL, '_blank', 'noopener')]
        ];
        const byScenario = {};
        if (this.state.games) {
            for (let entry of this.state.games) {
                if (!byScenario.hasOwnProperty(entry.scenario))
                    byScenario[entry.scenario] = [];
                byScenario[entry.scenario].push(entry);
            }
        }
        return (
            <main>
                <Helmet>
                    <title>{title} | Diplomacy</title>
                </Helmet>
                <Navigation title={title} navigation={navigation}/>
                <div className={'replays-intro my-3'}>
                    <p>
                        Replays of a rule-based Diplomacy agent I built for CITS3011 (Intelligent Agents) at UWA.
                        The agent uses breadth-first search over the map with heuristics for choosing targets,
                        coordinating supports and convoys. In each game it controls one power; the other six are
                        baseline agents, and games run from 1901 until a power holds 18 supply centres or 1920.
                    </p>
                    <p>
                        Pick a game and press <strong>Watch</strong>, then step through the phases with the arrows
                        under the map. Code and evaluation results are on <a href={REPO_URL} target={'_blank'}
                                                                            rel={'noopener noreferrer'}>GitHub</a>.
                    </p>
                </div>
                {this.state.games === null ? <p>Loading games ...</p> : (
                    Object.entries(byScenario).map(([scenario, games]) => this.renderScenario(scenario, games))
                )}
            </main>
        );
    }

    componentDidMount() {
        window.scrollTo(0, 0);
        const page = this.context;
        Promise.all([
            fetch(`${GAMES_DIR}/index.json`).then(response => response.json()),
            fetch(`${GAMES_DIR}/maps.json`).then(response => response.json())
        ])
            .then(([index, maps]) => {
                // Normally sent by the server on login; the game viewer needs it to draw orders.
                if (!page.availableMaps)
                    page.availableMaps = maps;
                this.setState({games: index.games});
                const requested = new URL(window.location.href).searchParams.get('game');
                const entry = requested && index.games.find(game => game.id === requested);
                if (entry)
                    return this.openGame(entry);
                setGameParam(null);
            })
            .catch(error => page.error(`Unable to load list of games: ${error}`));
    }
}

ContentReplays.contextType = PageContext;
